function renderCheckpointFavoriteComparisonOptions(){const panel=$('homeCheckpointFavoriteComparePanel'),a=$('homeCheckpointFavoriteCompareA'),b=$('homeCheckpointFavoriteCompareB');const favorites=currentUser&&cloudCheckpointOwner===currentUser?cloudCheckpointViews.filter(v=>v.is_favorite).sort((x,y)=>x.name.localeCompare(y.name)):[];panel.hidden=favorites.length<2;const previousA=a.value,previousB=b.value;a.replaceChildren();b.replaceChildren();for(const view of favorites){a.add(new Option(view.name,view.name));b.add(new Option(view.name,view.name))}if(favorites.some(v=>v.name===previousA))a.value=previousA;if(favorites.some(v=>v.name===previousB))b.value=previousB;else if(favorites.length>1)b.selectedIndex=1;$('homeCheckpointFavoriteCompareResult').replaceChildren()}
