function checkpointMonth(row){const date=new Date(row.created_at);return Number.isNaN(date.getTime())?'Unbekannt':date.toLocaleDateString('de-DE',{year:'numeric',month:'long'})}
function checkpointMonthKey(row){const date=new Date(row.created_at);return Number.isNaN(date.getTime())?'unknown':date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')}
const checkpointCategoryNames={layout:'Layouts',visibility:'Sichtbarkeit',metrics:'Kennzahlen',links:'Links & Favoriten',sorting:'Sortierung'};
function checkpointChangedGroups(row){return Object.entries(checkpointGroups).filter(([,keys])=>keys.some(k=>JSON.stringify(row.settings?.[k])!==JSON.stringify(preferences[k]))).map(([key])=>key)}
function renderCheckpointVisuals(rows,groups){const stats=$('homeCheckpointStats'),categories=$('homeCheckpointCategories'),monthly=$('homeCheckpointMonthly');stats.replaceChildren();categories.replaceChildren();monthly.replaceChildren();
 const changed=rows.filter(row=>checkpointChangedGroups(row).length).length;for(const [label,value] of [['Sicherungspunkte',rows.length],['Monate',groups.size],['Mit Unterschieden',changed]]){const card=el('div','');card.className='home-checkpoint-stat';card.append(el('strong',String(value)),el('span',label));stats.append(card)}
 for(const [key,name] of Object.entries(checkpointCategoryNames)){const count=checkpointRows.filter(row=>checkpointChangedGroups(row).includes(key)).length;if(!count&&!selectedCheckpointCategories.has(key))continue;const badge=el('button',name+' · '+count);badge.type='button';badge.className='home-checkpoint-category';badge.dataset.category=key;badge.setAttribute('aria-pressed',String(selectedCheckpointCategories.has(key)));badge.addEventListener('click',()=>{if(selectedCheckpointCategories.has(key))selectedCheckpointCategories.delete(key);else selectedCheckpointCategories.add(key);filterCheckpointRows()});categories.append(badge)}
 const max=Math.max(1,...[...groups.values()].map(g=>g.rows.length));for(const group of groups.values()){const row=el('div','');row.className='home-checkpoint-month-row';const label=el('span',group.name);const track=el('div','');track.className='home-checkpoint-month-track';track.setAttribute('role','img');track.setAttribute('aria-label',group.name+': '+group.rows.length+' Sicherungspunkte');const fill=el('div','');fill.className='home-checkpoint-month-fill';fill.style.width=(100*group.rows.length/max)+'%';track.append(fill);row.append(label,track,el('strong',String(group.rows.length)));monthly.append(row)}
}
function filterCheckpointRows(){
 const root=$('homeCheckpointEntries');root.replaceChildren();for(const id of ['homeCheckpointStats','homeCheckpointCategories','homeCheckpointMonthly'])$(id).replaceChildren();const nav=$('homeCheckpointMonths');nav.replaceChildren();$('homeCheckpointSummary').textContent='';if(!currentUser||checkpointOwner!==currentUser)return;
 const from=$('homeCheckpointFrom').value,to=$('homeCheckpointTo').value,field=$('homeCheckpointField').value,layout=$('homeCheckpointLayout').value;
 if(from&&to&&from>to){$('homeCheckpointStatus').textContent='Das Startdatum muss vor dem Enddatum liegen.';return}
 const rows=checkpointRows.filter(row=>{
 const day=row.created_at?.slice(0,10);
 if(from&&day<from||to&&day>to)return false;
 if(layout&&row.settings?.active_layout!==layout)return false;
 if(field&&!checkpointGroups[field]?.some(k=>JSON.stringify(row.settings?.[k])!==JSON.stringify(preferences[k])))return false;
 if(selectedCheckpointCategories.size&&![...selectedCheckpointCategories].every(k=>checkpointChangedGroups(row).includes(k)))return false;
 return true;
 });
 renderCheckpointFavoriteBar();
 $('homeCheckpointActiveCategories').textContent=selectedCheckpointCategories.size?'Zusätzliche Kategorien (alle müssen zutreffen): '+[...selectedCheckpointCategories].map(k=>checkpointCategoryNames[k]).join(', '):'Kategorien antippen, um sie zusätzlich zu den Datums- und Layoutfiltern zu kombinieren.';
 const monthGroups=new Map();for(const row of rows){const key=checkpointMonthKey(row);if(!monthGroups.has(key))monthGroups.set(key,{name:checkpointMonth(row),rows:[]});monthGroups.get(key).rows.push(row)}
 renderCheckpointVisuals(rows,monthGroups);
 let monthIndex=0;for(const [key,group] of monthGroups){const id='home-checkpoint-month-'+(++monthIndex);const link=el('a',group.name+' ('+group.rows.length+')');link.href='#'+id;nav.append(link)}
 const allDifferences=rows.reduce((count,row)=>count+Object.keys(compareFields).filter(k=>JSON.stringify(row.settings?.[k])!==JSON.stringify(preferences[k])).length,0);
 $('homeCheckpointSummary').textContent=rows.length+' Sicherungspunkte in '+monthGroups.size+' Monaten · '+allDifferences+' Feldabweichungen zur aktuellen Konfiguration insgesamt.';
 let lastMonth=null,renderMonth=0;
 for(const row of rows){
 const month=checkpointMonthKey(row);if(month!==lastMonth){lastMonth=month;renderMonth++;const group=monthGroups.get(month);const separator=document.createElement('li');separator.className='home-month-separator';const heading=el('h3',group.name+' · '+group.rows.length+' Sicherungspunkte');heading.id='home-checkpoint-month-'+renderMonth;heading.className='home-month-heading';const back=el('a','↑ Monate');back.href='#homeCheckpointMonths';heading.append(back);separator.append(heading);root.append(separator)}
 const item=document.createElement('li');const stamp=new Date(row.created_at).toLocaleString('de-DE');const time=document.createElement('time');time.dateTime=row.created_at;time.textContent=stamp;item.append(time);
 const layoutName={custom:'Individuell',compact:'Kompakt',daily:'Tagesplanung',overview:'Geschenküberblick'}[row.settings?.active_layout]||'Unbekannt';
 const tags=el('div','');tags.className='home-timeline-tags';tags.append(el('span','Layout: '+layoutName));const differing=Object.entries(compareFields).filter(([key])=>JSON.stringify(row.settings?.[key])!==JSON.stringify(preferences[key]));tags.append(el('span',differing.length+' Unterschiede zu heute'));for(const key of checkpointChangedGroups(row)){const badge=el('span',checkpointCategoryNames[key]);badge.className='home-checkpoint-category';badge.dataset.category=key;tags.append(badge)}item.append(tags);const short=differing.slice(0,3).map(([,label])=>label).join(' · ');item.append(el('p',differing.length?(short+(differing.length>3?' · +'+(differing.length-3)+' weitere':'')):'Keine Abweichung zur aktuellen Konfiguration.'));item.lastElementChild.className='home-timeline-summary';
 const detail=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Änderungsdetails anzeigen';detail.append(summary);
 const list=document.createElement('ul');
 if(!differing.length)list.append(el('li','Entspricht der aktuellen Konfiguration.'));
 for(const [key,label] of differing){const li=el('li','');li.append(el('strong',label+': '),document.createTextNode(compareValue(key,row.settings?.[key])+' → '+compareValue(key,preferences[key])));list.append(li)}
 detail.append(list);item.append(detail);
 const valid=safeHistorySettings({new_settings:row.settings});
 if(valid){const button=el('button','Mit aktueller Konfiguration vergleichen');button.type='button';button.addEventListener('click',()=>{if(currentUser!==checkpointOwner)return;renderCheckpointComparison(row);$('homeCheckpointStatus').textContent='Sicherungspunkt #'+row.id+' wird mit der aktuellen Konfiguration verglichen. Zur Wiederherstellung die Bestätigung im Vergleich verwenden.'});item.append(button)}
 else item.append(el('p','Dieser Sicherungspunkt enthält keine vollständig gültige Konfiguration.'));
 root.append(item)
 }
 if(!rows.length)root.append(el('p','Keine Sicherungspunkte entsprechen den Filtern.'));
 $('homeCheckpointStatus').textContent=rows.length+' von '+checkpointRows.length+' Sicherungspunkten angezeigt (maximal 20 pro Konto). Der Änderungsbereich bezieht sich auf Unterschiede zur aktuellen Konfiguration.';
}
function fillCheckpointCompareOptions(){for(const id of ['homeCheckpointCompareA','homeCheckpointCompareB']){const select=$(id),previous=select.value;select.replaceChildren(new Option('Bitte auswählen',''));for(const row of checkpointRows)select.add(new Option(new Date(row.created_at).toLocaleString('de-DE')+' · #'+row.id,String(row.id)));if(checkpointRows.some(row=>String(row.id)===previous))select.value=previous}if(checkpointRows.length>1){if(!$('homeCheckpointCompareA').value)$('homeCheckpointCompareA').value=String(checkpointRows[1].id);if(!$('homeCheckpointCompareB').value)$('homeCheckpointCompareB').value=String(checkpointRows[0].id)}}
$('homeCheckpointCompareShow').addEventListener('click',()=>{const root=$('homeCheckpointCompare');root.replaceChildren();if(!currentUser||checkpointOwner!==currentUser)return;const a=checkpointRows.find(r=>String(r.id)===$('homeCheckpointCompareA').value),b=checkpointRows.find(r=>String(r.id)===$('homeCheckpointCompareB').value);if(!a||!b||a.id===b.id){$('homeCheckpointCompareStatus').textContent='Bitte zwei unterschiedliche Sicherungspunkte auswählen.';return}const va=safeHistorySettings({new_settings:a.settings}),vb=safeHistorySettings({new_settings:b.settings});if(!va||!vb){$('homeCheckpointCompareStatus').textContent='Mindestens eine Konfiguration ist nicht vollständig gültig.';return}const table=el('table','');table.className='home-compare-table';const head=document.createElement('thead'),tr=document.createElement('tr');for(const title of ['Einstellung','Version A (#'+a.id+')','Version B (#'+b.id+')'])tr.append(el('th',title));head.append(tr);table.append(head);const body=document.createElement('tbody');let changed=0;for(const [key,label] of Object.entries(compareFields)){const diff=JSON.stringify(va[key])!==JSON.stringify(vb[key]);if(diff)changed++;const row=document.createElement('tr');row.dataset.changed=String(diff);row.append(el('th',label),el('td',compareValue(key,va[key])),el('td',compareValue(key,vb[key])));body.append(row)}table.append(body);root.append(table);$('homeCheckpointCompareStatus').textContent=changed+' von '+Object.keys(compareFields).length+' Feldern unterscheiden sich. Zum Wiederherstellen einen Sicherungspunkt in der Zeitachse mit der aktuellen Konfiguration vergleichen.'});
async function loadCheckpoints(){if(!currentUser||checkpointLoading)return;checkpointLoading=true;const owner=currentUser,root=$('homeCheckpointEntries');root.replaceChildren();$('homeCheckpointCompare').replaceChildren();comparedCheckpoint=null;$('homeCheckpointStatus').textContent='Sicherungspunkte werden geladen …';try{
 const {data,error}=await db.from('wishlist_gift_home_checkpoints').select('id,created_at,settings').eq('user_id',owner).order('id',{ascending:false}).limit(20);
 if(error)throw error;if(currentUser!==owner)return;
 checkpointRows=data||[];checkpointOwner=owner;await loadCloudCheckpointViews();fillCheckpointCompareOptions();
 if(!checkpointRows.length){for(const id of ['homeCheckpointStats','homeCheckpointCategories','homeCheckpointMonthly'])$(id).replaceChildren();$('homeCheckpointMonths').replaceChildren();$('homeCheckpointSummary').textContent='';root.append(el('p','Noch keine Sicherungspunkte. Der erste entsteht automatisch vor der nächsten Änderung an einer bestehenden Konfiguration.'));$('homeCheckpointStatus').textContent='Keine Sicherungspunkte vorhanden.';return}
 filterCheckpointRows();
 }catch(e){$('homeCheckpointStatus').textContent='Sicherungspunkte konnten nicht geladen werden.'}finally{checkpointLoading=false}}
for(const id of ['homeCheckpointFrom','homeCheckpointTo','homeCheckpointField','homeCheckpointLayout'])$(id).addEventListener('change',()=>{if(checkpointOwner===currentUser)filterCheckpointRows()});
$('homeCheckpointClear').addEventListener('click',()=>{for(const id of ['homeCheckpointFrom','homeCheckpointTo','homeCheckpointField','homeCheckpointLayout'])$(id).value='';selectedCheckpointCategories.clear();filterCheckpointRows()});
$('homeCheckpointReload').addEventListener('click',loadCheckpoints);
$('homeGiftCheckpoints').addEventListener('toggle',()=>{if($('homeGiftCheckpoints').open)loadCheckpoints()});
let historyLoading=false;
function settingsDiff(before,after){if(!before)return 'Erste gespeicherte Konfiguration';const names={show_metrics:'Kennzahlen sichtbar',show_tasks:'Tagesaufgaben sichtbar',show_occasions:'Anlässe sichtbar',show_progress:'Fortschritt sichtbar',task_sort:'Aufgabensortierung',occasion_sort:'Anlasssortierung',section_order:'Bereichsreihenfolge',metric_keys:'Kennzahlenauswahl',quick_links:'Schnellzugriffe',favorite_links:'Favoriten',saved_layouts:'Gespeicherte Vorlagen',active_layout:'Aktive Ansicht'};return Object.entries(names).filter(([key])=>JSON.stringify(before[key])!==JSON.stringify(after[key])).map(([,label])=>label).join(' · ')||'Keine sichtbare Änderung'}
function safeHistorySettings(row){const state=row?.new_settings;if(!state||!validSnapshot(state)||!['custom','compact','daily','overview'].includes(state.active_layout))return null;const saved=state.saved_layouts;if(!saved||typeof saved!=='object'||Array.isArray(saved)||Object.keys(saved).some(k=>!['compact','daily','overview'].includes(k)||!validSnapshot(saved[k])))return null;return {...snapshot(state),active_layout:state.active_layout,saved_layouts:saved}}
async function loadHistory(){if(!currentUser||historyLoading)return;historyLoading=true;const requestOwner=currentUser;$('homeHistoryStatus').textContent='Gespeicherte Änderungen werden geladen …';const root=$('homeHistoryEntries');root.replaceChildren();try{const {data,error}=await db.from('wishlist_gift_home_history').select('id,changed_at,action,previous_settings,new_settings').eq('user_id',currentUser).order('id',{ascending:false}).limit(30);if(error)throw error;if(currentUser!==requestOwner)return;fillHistorySelectors(data||[]);if(!data?.length){root.append(el('p','Noch keine protokollierten Änderungen seit Aktivierung des Verlaufs.'));$('homeHistoryStatus').textContent='Keine Einträge.';return}for(const row of data){const box=el('article','');box.className='home-history-entry';const stamp=new Date(row.changed_at).toLocaleString('de-DE');box.append(el('strong',stamp+' · '+(row.action==='created'?'Erstmals gespeichert':'Änderung gespeichert')),el('p',settingsDiff(row.previous_settings,row.new_settings)));const saved=safeHistorySettings(row);if(saved){const button=el('button','Diese Konfiguration wiederherstellen');button.type='button';button.addEventListener('click',()=>restoreHistoryVersion(row));box.append(button)}else box.append(el('p','Dieser ältere Eintrag ist nicht vollständig wiederherstellbar.'));root.append(box)}$('homeHistoryStatus').textContent='Die letzten '+data.length+' gespeicherten Änderungen (maximal 30).'}catch(e){$('homeHistoryStatus').textContent='Der private Verlauf konnte nicht geladen werden.'}finally{historyLoading=false}}
$('homeHistoryReload').addEventListener('click',loadHistory);
$('homeGiftHistory').addEventListener('toggle',()=>{if($('homeGiftHistory').open)loadHistory()});
function date(s){if(!s)return null;const [y,m,d]=s.slice(0,10).split('-').map(Number);return Date.UTC(y,m-1,d)}
function fmt(ms){return new Date(ms).toLocaleDateString('de-DE',{timeZone:'UTC',day:'2-digit',month:'2-digit',year:'numeric'})}
function next(o,today){const base=date(o.occasion_date);if(base===null)return null;if(!o.repeats_yearly)return base>=today?base:null;const [_,m,d]=o.occasion_date.split('-').map(Number);let year=new Date(today).getUTCFullYear();for(let i=0;i<3;i++,year++){const ms=Date.UTC(year,m-1,Math.min(d,new Date(Date.UTC(year,m,0)).getUTCDate()));if(ms>=today)return ms}return null}
function tile(root,title,body){const node=el('article','');node.className='home-gift-card';node.append(el('strong',title),el('p',body));root.append(node)}
async function rows(table,columns,uid,order){let result=[];for(let start=0;start<20000;start+=500){const {data,error}=await db.from(table).select(columns).eq('user_id',uid).order(order,{ascending:true}).range(start,start+499);if(error)throw error;result.push(...(data||[]));if((data||[]).length<500)return result}throw new Error('Zu viele Einträge für eine vollständige Übersicht')}
function render(tasks,occasions){const now=new Date(),today=Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()),active=tasks.filter(t=>!t.archived_at),open=active.filter(t=>t.status!=='done'),due=open.filter(t=>date(t.due_date)!==null&&date(t.due_date)<=today).map(t=>({task:t,days:Math.round((date(t.due_date)-today)/day)})).sort((a,b)=>(a.days<0?0:1)-(b.days<0?0:1)||(Number(a.task.priority)||2)-(Number(b.task.priority)||2)||a.days-b.days),upcoming=occasions.map(o=>({o,ms:next(o,today)})).filter(x=>x.ms!==null).sort((a,b)=>a.ms-b.ms);
 const metrics=$('homeGiftMetrics');const values={open:open.length,overdue:due.filter(x=>x.days<0).length,today:due.filter(x=>x.days===0).length,upcoming:upcoming.filter(x=>x.ms<=today+30*day).length,done:active.filter(t=>t.status==='done').length,completion_rate:(active.length?Math.round(100*active.filter(t=>t.status==='done').length/active.length):0)+' %'};for(const key of preferences.metric_keys)tile(metrics,String(values[key]),metricLabels[key]);renderLinks('homeGiftQuickLinks',preferences.quick_links);renderLinks('homeGiftFavorites',preferences.favorite_links);
 if(preferences.task_sort==='priority')due.sort((a,b)=>(Number(a.task.priority)||2)-(Number(b.task.priority)||2)||a.days-b.days);else if(preferences.task_sort==='due_date')due.sort((a,b)=>a.days-b.days||(Number(a.task.priority)||2)-(Number(b.task.priority)||2));if(preferences.occasion_sort==='title')upcoming.sort((a,b)=>a.o.title.localeCompare(b.o.title,'de'));const taskRoot=$('homeGiftTasks');if(!due.length)tile(taskRoot,'Heute gut aufgestellt','Keine offenen Aufgaben mit Fälligkeit bis heute.');for(const x of due.slice(0,3)){const priority=({1:'hoch',2:'mittel',3:'niedrig'})[x.task.priority]||'mittel';tile(taskRoot,x.task.title,(x.days<0?'Seit '+Math.abs(x.days)+' Tagen überfällig':'Heute fällig')+' · Priorität '+priority+'. Empfehlung: '+(x.days<0?'Zuerst nachholen.':'Heute bearbeiten.'))}
 const occRoot=$('homeGiftOccasions');if(!upcoming.length)tile(occRoot,'Noch kein nächster Anlass','Erstelle einen Anlass, um Planungsempfehlungen zu erhalten.');for(const x of upcoming.slice(0,3)){const days=Math.round((x.ms-today)/day);tile(occRoot,x.o.title,fmt(x.ms)+' · '+(days===0?'Heute':days+' Tage verbleibend')+'. '+(days<=21?'Empfehlung: Planung jetzt beginnen.':'Planungsbeginn empfohlen ab '+fmt(x.ms-21*day)+'.'))}
 const completed=active.filter(t=>t.status==='done').length;$('homeGiftProgress').max=active.length||1;$('homeGiftProgress').value=completed;$('homeGiftProgressText').textContent=completed+' von '+active.length+' nicht archivierten Aufgaben aktuell erledigt ('+(active.length?Math.round(100*completed/active.length):0)+' %).';
 applyPreferences();$('homeGiftStatus').textContent='Privater Überblick – nur für dein angemeldetes Konto. Keine Daten verändert.';
}
let loading=false,loadedFor=null,refreshPending=false,authRevision=0;
async function refresh(){if(loading){refreshPending=true;return}loading=true;const authVersion=authRevision;try{const {data,error}=await db.auth.getUser();if(authVersion!==authRevision)return;const uid=data?.user?.id;if(error||!uid){$('homeGiftStart').hidden=true;loadedFor=null;currentUser=null;currentTasks=[];currentOccasions=[];preferences={...defaults};draftOrder=[...sections];previewSnapshot=null;previewTarget=null;previewFormDraft=null;$('homePreviewUndo').disabled=true;$('homeConfirmPreview').disabled=true;$('homeSettingsStatus').textContent='';$('homeLayoutStatus').textContent='';$('homeHistoryEntries').replaceChildren();$('homeCheckpointEntries').replaceChildren();$('homeCheckpointMonths').replaceChildren();$('homeCheckpointSummary').textContent='';$('homeCheckpointCompare').replaceChildren();comparedCheckpoint=null;checkpointRows=[];checkpointOwner=null;selectedCheckpointCategories.clear();cloudCheckpointViews=[];cloudCheckpointOwner=null;$('homeCheckpointFavoriteBar').replaceChildren();$('homeCheckpointFavoriteStatus').textContent='';$('homeCheckpointViewCards').replaceChildren();$('homeCheckpointViewPreview').replaceChildren();for(const id of ['homeCheckpointStats','homeCheckpointCategories','homeCheckpointMonthly'])$(id).replaceChildren();$('homeCompareResult').replaceChildren();historyVersions=[];historyOwner=null;clearPendingBackup();$('homeBackupFile').value='';return}if(loadedFor===uid)return;if(currentUser&&currentUser!==uid){previewSnapshot=null;previewTarget=null;previewFormDraft=null;$('homePreviewUndo').disabled=true;$('homeConfirmPreview').disabled=true;$('homeSettingsStatus').textContent='';$('homeLayoutStatus').textContent='';currentUser=null}loadedFor=null;$('homeGiftStart').hidden=false;$('homeGiftStatus').textContent='Dein privater Geschenk-Überblick wird geladen …';const [tasks,occasions]=await Promise.all([rows('wishlist_gift_tasks','id,title,due_date,status,priority,archived_at',uid,'created_at'),rows('wishlist_occasions','id,title,occasion_date,repeats_yearly',uid,'occasion_date')]);if(authVersion!==authRevision)return;if(!await loadPreferences(uid,authVersion))return;if(authVersion!==authRevision)return;currentUser=uid;currentTasks=tasks;currentOccasions=occasions;for(const id of ['homeGiftMetrics','homeGiftTasks','homeGiftOccasions'])$(id).replaceChildren();render(tasks,occasions);loadedFor=uid}catch(e){if(authVersion===authRevision)$('homeGiftStatus').textContent='Privater Überblick derzeit nicht verfügbar. Öffne das Geschenk-Planungscockpit für Details.'}finally{loading=false;if(refreshPending){refreshPending=false;refresh()}}}
db.auth.onAuthStateChange(()=>{++authRevision;setTimeout(refresh,0)});
refresh();
